+#[test]
+fn legacy_contiguous_small_scratch_is_direct_and_reused() {
+    struct Legacy<'a> {
+        bytes: usize,
+        pointers: &'a RefCell<Vec<usize>>,
+    }
+    impl CodecMessage for Legacy<'_> {
+        fn encoded_len(&self) -> usize {
+            self.bytes
+        }
+        fn encode_payload<W: WireOut>(&self, out: &mut W) -> Result<(), Status> {
+            out.write_contiguous(|bytes| {
+                assert!(bytes.capacity() >= self.bytes);
+                self.pointers.borrow_mut().push(bytes.as_ptr() as usize);
+                bytes.resize(self.bytes, 0x91);
+            });
+            Ok(())
+        }
+        fn encode_payload_bufmut<B: bytes::BufMut>(&self, _: &mut B) -> Result<(), Status> {
+            panic!("default-off legacy path must not use the append-only bridge")
+        }
+        fn decode_payload(_: Bytes) -> Result<Self, Status> {
+            panic!("encode only")
+        }
+        fn empty() -> Self {
+            panic!("encode only")
+        }
+    }
+    let pointers = RefCell::new(Vec::new());
+    let message = Legacy {
+        bytes: 1024,
+        pointers: &pointers,
+    };
+    let mut scratch = EncodeScratch::new();
+    for _ in 0..4 {
+        scratch
+            .with_payload(&message, message.encoded_len(), |bytes| {
+                assert_eq!(bytes, vec![0x91; 1024]);
+                Ok(())
+            })
+            .expect("legacy direct encode");
+        assert_eq!(scratch.capacity(), 1024);
+        assert!(scratch.lease_capacity().is_none());
+    }
+    let pointers = pointers.borrow();
+    assert_eq!(pointers.len(), 4);
+    let first = pointers.first().expect("four recorded pointers");
+    assert!(pointers.iter().all(|pointer| pointer == first));
+}
